<div class='page-header mb-3'><div class='row align-items-center'><div class='col'><h2 class='page-title'><?=e($journal['journal_no'])?></h2><div class='text-secondary'><?=e($journal['description'])?></div></div><?php if($journal['status']==='draft'):?><div class='col-auto d-flex gap-2'><a class='btn btn-outline-primary' href='/accounting/journals/<?=e($journal['id'])?>/edit'>تعديل</a><form method='post' action='/accounting/journals/<?=e($journal['id'])?>/post'><input type='hidden' name='_token' value='<?=e($csrfToken)?>'><button class='btn btn-primary'>ترحيل</button></form></div><?php endif;?></div></div><div class='card'><div class='card-body'><b>التاريخ:</b> <?=e($journal['journal_date'])?> · <b>الحالة:</b> <?=$journal['status']==='posted'?'مرحّل':'مسودة'?></div><table class='table'><thead><tr><th>الحساب</th><th>الوصف</th><th>مدين</th><th>دائن</th></tr></thead><tbody><?php foreach($lines as$l):?><tr><td><?=e($l['account_code'].' - '.$l['account_name'])?></td><td><?=e($l['description'])?></td><td><?=decimal_format((string)$l['debit'])?></td><td><?=decimal_format((string)$l['credit'])?></td></tr><?php endforeach;?></tbody></table></div>
